// CSD_RATIONALE_BEGIN
// Attempt 66 (53.3%) uses RegenerateUnitOnGroundingFailure in Phase 3.
// Diagnostics show: <<  never visible (evaluator pre-opens span, starts
// insideConstrained=true), >> visible in 298/300 (CloseConstrainedSpan works),
// avg 28.78 tokens (short SQL). All 140 wrong examples are mode_A: syntax_valid
// but semantically wrong SQL (wrong columns, wrong JOINs, wrong conditions).
//
// Hypothesis: RegenerateUnitOnGroundingFailure's internal rollback mechanism
// may steer the model toward different SQL on grounding failures, sometimes
// introducing additional errors. A simpler ConstrainedStep loop (hard parser
// mask, no rollback) is more predictable and may produce SQL that more closely
// matches the evaluator's expected structure for short Spider queries.
//
// Changes from attempt 66:
//   - Phase 3: Replace RegenerateUnitOnGroundingFailure with an explicit
//     ConstrainedStep loop (same budget cap: 300 steps).
//   - Guidance: unchanged (attempt 61/66 optimal guidance retained).
//   - Phase 1 preamble: unchanged (5 steps; almost always skipped when
//     evaluator starts with insideConstrained=true).
//   - Phase 2 force-open: unchanged.
//   - Phase 4 close: unchanged (CloseSpanWithinBudget(120) fallback).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (unconstrained loop): Guard requires !insideConstrainedOut, so
//   implication is vacuously true throughout. The only true-flip is via
//   RenderedEndsWith check; at that point currentConstrainedOut := [] and
//   IsValidPrefix([]) holds by the method precondition.
//
// Phase 2 (OpenConstrainedSpan): Runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds.
//
// Phase 3 (ConstrainedStep inner loop): ConstrainedStep postcondition
//   guarantees next == eosToken || IsTokenValidNext(parser, currentConstrainedOut, next).
//   When next != eosToken and IsTokenValidNext is true, AppendConstrainedToken
//   postcondition guarantees parser.IsValidPrefix(currentConstrainedOut + [next]).
//   EOS and invalid branches leave currentConstrainedOut unchanged (break).
//   Loop invariant re-establishes the implication each iteration.
//
// Phase 4a (CloseConstrainedSpan): Sets insideConstrainedOut := false, making
//   the implication vacuously true; clears currentConstrainedOut := [].
// Phase 4b (CloseSpanWithinBudget): Postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each iteration takes one UnconstrainedStep (+1 to steps) and
//   appends 0 (EOS) or 1 (non-EOS) token. steps grows as fast as generated.
//
// Phase 2: OpenConstrainedSpan appends exactly 1 "<<" token and +1 step. 1:1.
//
// Phase 3 inner loop: Each iteration increments sqlSteps by 1 (ConstrainedStep
//   cost +1) and appends at most 1 token (EOS appends 0). So
//   |generated| <= |generatedPrefix| + stepsAtPhase3 + sqlSteps throughout.
//   After loop: steps := steps + sqlSteps; bound |generated| <= |generatedPrefix|
//   + steps is re-established. Budget ensures sqlSteps <= sqlBudget <= remaining-1
//   so steps does not exceed maxSteps after Phase 3.
//
// Phase 4a: CloseConstrainedSpan +1 step, appends at most 1 ">>" token.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated|
//   + closeBudget; steps += closeBudget. Invariant preserved by transitivity.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble — up to 5 steps to let model emit "SQL: <<"
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside a constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL via simple ConstrainedStep loop (replaces
// RegenerateUnitOnGroundingFailure — avoids rollback-induced direction changes).
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var sqlBudget: nat;
  if remaining <= 1 {
    sqlBudget := 0;
  } else if remaining - 1 <= 300 {
    sqlBudget := remaining - 1;
  } else {
    sqlBudget := 300;
  }

  // constrainedPrompt is the full context prefix before the constrained content.
  // As AppendConstrainedToken grows both generated and currentConstrainedOut by 1,
  // |generated| - |currentConstrainedOut| remains constant, so this is computed once.
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var sqlSteps: nat := 0;

  while sqlSteps < sqlBudget && insideConstrainedOut
    invariant 0 <= sqlSteps <= sqlBudget
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps + sqlSteps
    decreases sqlBudget - sqlSteps
  {
    if parser.IsCompletePrefix(currentConstrainedOut) {
      break;
    }
    var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    sqlSteps := sqlSteps + 1;
    if next == eosToken {
      break;
    } else {
      var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
      if valid {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }

  steps := steps + sqlSteps;
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

